333	  const r = raw as Record<string, unknown>;
334	  const severity = normalizeSeverity(r.severity);
335	  if (!severity) return null;
336	  return {
337	    id: typeof r.id === "string" && r.id.length > 0 ? r.id : `I${index + 1}`,
338	    region:
