357	function extractJsonObject(text: string): string | null {
358	  const start = text.indexOf("{");
359	  if (start < 0) return null;
360	  let depth = 0;
361	  let inString = false;
362	  let escape = false;
363	  for (let i = start; i < text.length; i++) {
364	    const ch = text[i]!;
365	    if (escape) {
366	      escape = false;
367	      continue;
368	    }
369	    if (ch === "\\") {
370	      escape = true;
371	      continue;
372	    }
373	    if (ch === '"') {
